fn extract(condition: Vec<bool>, arr: Vec<f32>) -> Vec<f32> {
    // We assume `condition.len() == arr.len()`
    assert_eq!(condition.len(), arr.len());

    // Pre-compute how many `true` values there are so we can reserve capacity.
    let true_count = condition.iter().filter(|&&c| c).count();

    let mut result = Vec::with_capacity(true_count);
    for (keep, value) in condition.into_iter().zip(arr.into_iter()) {
        if keep {
            result.push(value);
        }
    }
    result
}

